import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq)
    sell_heap = []  # entries: (price, seq)
    book = {}       # id -> dict(side, price, qty, seq, active)
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def get_top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid, o
        return None, None

    def match_incoming(side, price, qty, incoming_id, is_market_or_ioc_price_limit=True, unlimited=False):
        # returns remaining qty
        remaining = qty
        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            oid, o = get_top_valid(opp_heap)
            if oid is None:
                break
            resting_price = o['price']
            if not unlimited:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break
            trade_qty = min(remaining, o['qty'])
            if side == 'buy':
                trades.append([incoming_id, oid, resting_price, trade_qty])
            else:
                trades.append([oid, incoming_id, resting_price, trade_qty])
            o['qty'] -= trade_qty
            remaining -= trade_qty
            if o['qty'] <= 0:
                o['active'] = False
                heapq.heappop(opp_heap)
            # if still qty>0, leave at top for next iteration check (it will be reused)
            else:
                # can't fully satisfy incoming, so remaining must be 0, loop ends anyway
                pass
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active']:
                o['active'] = False
                o['qty'] = 0
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            seq = seq_counter
            seq_counter += 1
            remaining = match_incoming(side, price, qty, oid, unlimited=False)
            if remaining > 0:
                add_to_book(oid, side, price, remaining, seq)
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            seq = seq_counter
            seq_counter += 1
            remaining = match_incoming(side, price, qty, oid, unlimited=False)
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            seq = seq_counter
            seq_counter += 1
            remaining = match_incoming(side, None, qty, oid, unlimited=True)
            book[oid] = {'side': side, 'price': None, 'qty': 0, 'seq': seq, 'active': False}

    return trades

